contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the minimal sequence: ensure recipient hasn't claimed, grant bonus via getFirstWithdrawalBonus,
    // then observe balances before and after withdrawReward.
    // Parameters:
    // - recipient: target address to receive bonus/withdrawal
    // - sendAmount: amount of ETH the test contract funds itself with if needed (not used here but allowed)
    function run(address payable recipient, uint /*sendAmount*/) public {
        // precondition: recipient is not this contract to avoid self-transfer side-effects
        require(recipient != address(this));

        // record balances before any interaction
        uint balBeforeRecipient = recipient.balance;
        uint balBeforeContract = address(c).balance;

        // Give recipient its first bonus and trigger immediate withdrawal
        c.getFirstWithdrawalBonus(recipient);

        // record balances after the withdrawal
        uint balAfterRecipient = recipient.balance;
        uint balAfterContract = address(c).balance;

        // The intended rule: recipient's balance increases exactly by 100 and the contract's balance decreases by exactly 100
        // This distinguishes the mutant which would leave 1 wei stored and thus not reduce contract balance by full 100.
        assert(balAfterRecipient - balBeforeRecipient == 100 && balBeforeContract - balAfterContract == 100);
    }

    // allow receiving ETH if needed by the environment
    receive() external payable {}
}

