        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        // Precondition: ensure the caller does not supply Ether and we only test withdraw on recipient
        require(recipient != address(0));
        // Ensure we do not send Ether to C in this test; not necessary but narrows inputs
        // Call withdrawReward and record whether it reverts
        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }
        // In the original contract, if rewardsForA[recipient] == 0 then withdrawReward reads 0
        // and sending 0 value does not cause revert. So for any recipient with zero reward, call must not revert.
        // We cannot read rewardsForA (private), so we express zero-reward by observing that calling withdrawReward twice
        // in a row should not revert on the first call when there was zero stored value. However we are constrained
        // to a single state-changing call here, so instead we require that withdraw on an address that is unlikely
        // to have funds (no prior interactions) does not revert. To make this general, assert that for any recipient
        // if the call reverted then it must have been nonzero reward — equivalently, if reverted == true then
        // the call could not have been on an address with zero reward. Since we cannot observe internal reward,
        // we assert the intended property directly: withdraw on an address with zero reward does not revert.
        // To encode this without reading private state, we take the conservative precondition that the recipient
        // is the test contract itself which has not been credited with rewards in setup; require address(this) != recipient
        // would break generality, so instead we assert that the call did not revert (the property to hold).
        assert(!reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        // ensure SmartFix is not locked: call any non-state-changing function isn't available,
        // but the modifier uses internal _locked flag which starts false. To be safe, require true.
        require(true);
        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }
        // In the original contract withdrawReward always succeeds when not locked; assert it did not revert
        assert(reverted == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take the recipient as a parameter. The rule: when the contract is unlocked
    // and sending the current stored reward to recipient would succeed, withdrawReward
    // must not revert.
    function run(address payable recipient) public payable {
        // require the contract is unlocked in SmartFix (its default is unlocked false),
        // but we can't read _locked (it's public in SmartFix? it's public bool _locked = false;)
        // However, per constraints we may only observe through public surface of C.
        // To ensure the contract is in unlocked state we require true (default),
        // and we ensure the recipient is a payable address different from this contract so that
        // the external call can succeed. Also require non-zero gas forwarding isn't needed.
        require(recipient != address(0));

        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }

        // General rule: withdrawReward should not revert for any recipient address that is a valid non-zero address.
        // This holds for the original implementation but the mutant may revert when it tries to set a non-zero storage value.
        assert(reverted == false);
    }

    receive() external payable { }
}

