pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary recipient address (the fuzzer will supply EOAs and contract addresses).
    // We must ensure the recipient can receive ETH, so fund it. We keep domain wide.
    function testFuzz_property(address recipient) public {
        // avoid zero address to keep meaningful scenario (still wide)
        vm.assume(recipient != address(0));

        // Fund the contract so it can pay out the bonus
        vm.deal(address(c), 1 ether);

        // Ensure recipient can receive funds (EOA by default). Call the entry point.
        // The property: after getFirstWithdrawalBonus(recipient) completes, rewardsForA[recipient] == 0
        // We observe this via the autogenerated public getter rewardsForA(address) -> uint.

        // call the public entry that increases reward and triggers withdraw
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // We only assert the universal property about state when the call succeeded
        // (the reference always succeeds for admissible inputs); mutant may also succeed but leave non-zero.
        if (ok) {
            // exactly one assertion reading c's public surface: rewardsForA getter
            // The reference contract guarantees this is zero for all recipients after the call.
            assertTrue(c.rewardsForA(recipient) == 0);
        } else {
            // If the call reverted, still assert using a public observation: in the reference this should not happen
            // but we must make a single assertion in all executions; check that call succeeded (so reference holds)
            // This assertion will fail on mutant for some inputs where mutant leaves non-zero but call succeeds.
            // To satisfy the single-assert rule in all paths, assert the call succeeded.
            assertTrue(ok);
        }
    }
}

