pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: an address that will act as recipient and a uint amount seed (kept wide)
    function testFuzz_property(address recipient, uint256 seed) public {
        // We need an adversarial recipient that reverts on receive so the mutant behaves differently.
        // Fuzzer gives arbitrary address; deploy an on-chain Reverter and use its address as recipient.
        // Keep domain wide but avoid zero address for recipient to be sensible.
        vm.assume(recipient != address(0));

        // Deploy adversarial callee that always reverts when receiving ETH
        Reverter rev = new Reverter();

        // Use the reverter as the recipient to trigger failing external call in withdrawReward
        address bad = address(rev);

        // Ensure the contract has no Ether initially and that rewardsForA is manipulated only via getFirstWithdrawalBonus
        // The reference contract behavior: getFirstWithdrawalBonus increments rewardsForA by 100, then calls withdrawReward
        // which should clear rewardsForA[bad] to 0 even if the external call reverts (because state reset happens before call in ref).

        // Give c some ETH so it can attempt to send
        vm.deal(address(c), 1 ether);

        // Call getFirstWithdrawalBonus targeting the reverter; this will attempt to withdraw (which will revert on send)
        // We call in a try/catch to allow the test to continue regardless of revert outcome.
        bool ok;
        try c.getFirstWithdrawalBonus(bad) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after calling getFirstWithdrawalBonus against any admissible recipient (here: reverter),
        // the stored rewardsForA for that recipient must be zero on the reference implementation.
        // We observe this via the autogenerated getter rewardsForA(address) which is private in source, but the problem statement
        // allowed observing only public surfaces — however rewardsForA is private. To respect the constraint, we instead
        // observe that calling withdrawReward again for the same recipient on the reference will revert with zero-value send (or succeed but send 0),
        // but that is not a reliable public observation. Instead, we use the public behavior: after the operation, calling getFirstWithdrawalBonus a second time
        // should still allow claiming the bonus (since claimedBonus remains false if first call reverted during external send in mutant vs ref). To keep to the rule
        // and keep a single assert reading c, we use a try on withdrawReward(bad) and assert that withdrawReward DOES NOT send funds (i.e., it will not revert due to non-zero rewards).
        // However, the simplest direct observable is to call getFirstWithdrawalBonus again and observe whether it reverts due to claimedBonus already set.

        // Call getFirstWithdrawalBonus again and see whether it reverts due to claimedBonus being set. On the reference, even if the external transfer to bad reverted,
        // claimedBonus is set to true only after withdrawReward returns; since withdrawReward in reference clears rewards before the external call, claimedBonus will still become true
        // and the second call should revert because claimedBonus[bad] == true. On the mutant, when external call reverts, rewardsForA wasn't cleared and claimedBonus is not set,
        // so the second call might not revert. Therefore, we assert that the second call reverts (ok2 == false) as the universal property for the reference.

        bool ok2;
        try c.getFirstWithdrawalBonus(bad) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The single assertion: on the reference contract, the second attempt to getFirstWithdrawalBonus for the same recipient must revert (claimedBonus already set),
        // so ok2 must be false for ALL admissible inputs. The mutant will allow ok2 == true for some inputs (the reverter), so the test will fail on the mutant.
        assertTrue(!ok2);
    }
}

// Adversarial helper: always revert on receive to simulate a failing external callee
contract Reverter {
    receive() external payable {
        revert("nope");
    }

    fallback() external payable {
        revert("nope");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial balance (so it can receive ETH) and a nonzero reward amount
    function testFuzz_property(address attacker, uint256 rewardAmount) public {
        // Keep domains wide but sensible
        vm.assume(attacker != address(0));
        // ensure rewardAmount is small enough to supply via vm.deal in test environment
        rewardAmount = bound(rewardAmount, 1, 1 ether);

        // Deploy a helper that REVERTS on receive to simulate a failing external call
        Reverter rev = new Reverter();

        // Fund the contract's rewards mapping by directly calling C.getFirstWithdrawalBonus on an address we control.
        // The C.getFirstWithdrawalBonus adds 100 then calls withdrawReward(recipient).
        // To make rewardsForA[recipient] reflect a larger amount, we instead simulate by calling withdrawReward path
        // through manipulating the rewardsForA mapping is private, so we leverage the public flows: we will first set up
        // rewards by calling a first bonus to the Reverter with an extra fund in contract balance.

        // Ensure the contract has enough ETH to attempt payouts
        vm.deal(address(c), 1 ether);

        // Note: getFirstWithdrawalBonus will add 100 and then call withdrawReward which will attempt to send to Reverter and REVERT.
        // For the reference contract, despite the external revert, rewardsForA[reverter] should be cleared (because reset occurs before external call).
        // For the mutant, rewardsForA[reverter] will remain non-zero because reset is after the external call which reverted.

        // Call getFirstWithdrawalBonus with the reverter address (it will revert internally due to withdrawReward revert).
        // We expect the external call to revert; capture that behavior.
        bool ok;
        try c.getFirstWithdrawalBonus(address(rev)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Ensure the external call indeed reverted (this is the admissible scenario we constructed)
        // If it did not revert (unexpected), we still continue; the property we're asserting must hold for all admissible inputs,
        // and the adversarial helper ensures revert, so ok should be false. Keep wide assumptions: require revert occurred.
        // Use vm.assume to only keep traces where the external interaction failed (this is the adversarial domain we need).
        vm.assume(ok == false);

        // After the failed withdrawal, in the reference C rewardsForA[reverter] must be zero. We detect this indirectly by
        // calling withdrawReward again: if rewardsForA is zero, withdrawReward will attempt to send 0 value and should succeed (no revert) on reference.
        // For the mutant, rewardsForA may still be non-zero, so withdrawReward will attempt to send a positive amount to Reverter and will revert.
        bool ok2;
        try c.withdrawReward(address(rev)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Exactly one assertion reading c: on the reference contract for all admissible inputs (we restricted to cases where the first withdraw reverted),
        // withdrawReward(second call) should succeed (ok2 == true). The mutant will fail this for some inputs (it will revert because balance remains non-zero).
        assertTrue(ok2);
    }
}

// adversarial helper that reverts on receive/call
contract Reverter {
    receive() external payable {
        revert("nope");
    }
    fallback() external payable {
        revert("nope");
