        // ensure rev address is what we pass as recipient (we fuzz recipient but must pass actual contract address to c)
        // We don't change the shape: fuzzed param is `recipient`. Use it as a selector: if low 160 bits match rev, use it, else use rev.
        // But to keep fuzz parameter meaningful, allow both: if recipient equals rev, use it; otherwise use rev anyway.
        address target = address(rev);

        // drive the contract: call getFirstWithdrawalBonus forwarding target as the recipient
        bool ok;
        try c.getFirstWithdrawalBonus(target) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: on the correct contract, after the call either it reverted (ok==false) and claimedBonus[target]==false,
        // or it succeeded (ok==true) and claimedBonus[target]==true.
        // We can observe claimedBonus via the auto-generated getter `claimedBonus(address)` because in the reference it is declared public.
        // The single assertion checks that claimedBonus[target] == ok.
        assertTrue(c.claimedBonus(target) == ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("fail");
    }
    receive() external payable {
        revert("fail");
    }
}

